<?php
namespace App\Http\Controllers;
use App\Models\{Member,MembershipCategory,MembershipLevel,User}; use Illuminate\Http\Request; use Illuminate\Support\Str; use Illuminate\Validation\Rule;
class MemberController extends Controller {
 private function admin(){abort_unless(in_array(auth()->user()->role,['admin']),403);}
 public function index(Request $r){$this->admin();$members=Member::with(['membershipCategory','membershipLevel'])->when($r->filled('search'),fn($q)=>$q->where(fn($x)=>$x->where('member_code','like','%'.$r->search.'%')->orWhere('first_name','like','%'.$r->search.'%')->orWhere('last_name','like','%'.$r->search.'%')->orWhere('email','like','%'.$r->search.'%')))->when($r->filled('category'),fn($q)=>$q->where('membership_category_id',$r->category))->when($r->filled('level'),fn($q)=>$q->where('membership_level_id',$r->level))->latest()->paginate(12)->withQueryString();return view('members.index',compact('members')+['categories'=>MembershipCategory::all(),'levels'=>MembershipLevel::all()]);}
 public function create(){$this->admin();return view('members.form',['member'=>new Member,'categories'=>MembershipCategory::where('is_active',true)->get(),'levels'=>MembershipLevel::where('is_active',true)->get(),'users'=>User::where('role','student')->doesntHave('member')->get()]);}
 public function store(Request $r){$this->admin();$d=$this->validateMember($r);$user=$d['user_id']?User::findOrFail($d['user_id']):null;$cat=MembershipCategory::findOrFail($d['membership_category_id']);$level=MembershipLevel::findOrFail($d['membership_level_id']);$member=Member::create($d+['member_code'=>'PUH-'.now()->format('ymd').'-'.Str::upper(Str::random(5)),'category'=>$cat->name,'level'=>$level->name,'joined_at'=>now()->toDateString(),'status'=>'Active']);return redirect()->route('members.show',$member)->with('success','Member created.');}
 public function show(Member $member){$this->admin();$member->load(['membershipCategory','membershipLevel','transactions.payments']);return view('members.show',compact('member'));}
 public function edit(Member $member){$this->admin();return view('members.form',['member'=>$member,'categories'=>MembershipCategory::all(),'levels'=>MembershipLevel::all(),'users'=>User::where('role','student')->where(function($q)use($member){$q->whereDoesntHave('member')->orWhere('id',$member->user_id);})->get()]);}
 public function update(Request $r,Member $member){$this->admin();$d=$this->validateMember($r);$cat=MembershipCategory::findOrFail($d['membership_category_id']);$level=MembershipLevel::findOrFail($d['membership_level_id']);$member->update($d+['category'=>$cat->name,'level'=>$level->name]);return redirect()->route('members.show',$member)->with('success','Member updated.');}
 public function destroy(Member $member){$this->admin();$member->update(['status'=>'Inactive']);return redirect()->route('members.index')->with('success','Member deactivated; transaction history preserved.');}
 public function toggleStatus(Member $member){$this->admin();$newStatus=$member->status==='Active'?'Inactive':'Active';$member->update(['status'=>$newStatus]);$message=$newStatus==='Active'?'Member reactivated successfully.':'Member deactivated; transaction history preserved.';return redirect()->route('members.show',$member)->with('success',$message);}
 private function validateMember(Request $r):array{$member=$r->route('member');return $r->validate(['user_id'=>['nullable','exists:users,id',Rule::unique('members','user_id')->ignore($member?->id)],'first_name'=>'required|string|max:100','last_name'=>'required|string|max:100','email'=>'required|email|max:255','phone'=>'nullable|string|max:30','address'=>'nullable|string|max:500','membership_category_id'=>'required|exists:membership_categories,id','membership_level_id'=>'required|exists:membership_levels,id','latitude'=>'nullable|numeric|between:-90,90','longitude'=>'nullable|numeric|between:-180,180']);}
}
